INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(40600, 0, 406, 0, 0, 0, 'Stonetalon Mountains', 'The Stonetalon Mountains rise west of the Barrens and south of Ashenvale, a range of forested peaks, deep canyons and mountain lakes, and both tauren and night elves have long held its great peak sacred. In the Third War, Jaina Proudmoore and Thrall each came to the caverns of Stonetalon Peak seeking the Oracle, and there the prophet Medivh urged orc and human to set aside old hatreds and stand together against the Burning Legion. Today the mountains are wounded. The Venture Company is stripping Windshear Crag of its forests, and the fires of its machines left the Charred Vale a blackened ruin of raging elementals and Bloodfury harpies. The spirits of the land cry out in pain, and both the Horde and the night elves have heard them. The Horde holds Sun Rock Retreat and the troll camp of Malaka''jin, while the night elves keep a small outpost on Stonetalon Peak beside the barrow of the Talon Den. Grimtotem tauren prowl the southeastern valleys, spiders haunt the Webwinder Path, and kobolds dig deep beneath Boulderslide Ravine.', 'warcraft.wiki.gg/wiki/Stonetalon_Mountains (sacred to tauren and night elves; Third War, Stonetalon Peak caverns, Oracle/Medivh, Alliance and Horde briefly united); warcraft.wiki.gg/wiki/Stonetalon_Peak (Jaina''s expedition and Thrall at the peak caverns); quest 1061 and 1062 descriptions (spirits angered, deforestation); quest 1057 description (Charred Vale set afire by industrialists); quest 1083 description (elementals released); zone_areas: Sun Rock Retreat, Malaka''jin, Stonetalon Peak, Talon Den, Grimtotem Post, Webwinder Path, Boulderslide Ravine spawns; warcraft.wiki.gg/wiki/Stonetalon_Mountains (Stonetalon Peak sacred to night elves and tauren; Oracle; Alliance and Horde temporarily united in the peak caverns)'),
(40601, 1, 406, 1, 0, 0, 'Greatwood Vale', 'The Greatwood Vale lies in the southeast of the mountains, where the road running west from the Crossroads climbs out of the Barrens. The Horde shaman Seereth Stonebreak keeps her camp near its edge, at the border of the two lands, and from there the way leads on to the northwest toward the logging grounds of Windshear Crag. The vale is not safe. Grimtotem mercenaries and ruffians roam its woods in great numbers, with brutes and sorcerers among them. Close to the troll camp of Malaka''jin, night elves sit caged in the vale as prisoners of the witch doctor Jin''Zil.', 'quest 1061 description (road west of the Crossroads, camped near the Greatwood Vale); quest 1062 and 1068 descriptions (Windshear Crag northwest beyond the Greatwood Vale); zone_areas area 469: Grimtotem Mercenary 32, Ruffian 15, Brute 5, Sorcerer 2, Prisoner of Jin''Zil 2; posarea: Seereth Stonebreak stands just inside the Barrens (area 17) at the border; quest 1058 description (three little cages for three little elves)'),
(40602, 1, 406, 2, 0, 0, 'Malaka''jin', 'Malaka''jin is a small troll camp at the base of the mountains, in the far southeast near the Barrens. Its people live well off the hunting in these hills, though lately spiders have been creeping into the camp by night to steal their kills, and Xen''Zilla wants the beasts thinned. In his cave at the camp, the witch doctor Jin''Zil keeps caged night elves and bubbling cauldrons of his own brews. Ken''zigla prepares healing draughts for wounded Horde soldiers as far off as Camp Taurajo, and Darn Talongrip sends willing recruits north to join the Horde campaign in Ashenvale.', 'quest 6461 description (trolls prosper from hunting; spiders raid camps at night to steal the hunt); quest 1510 description (healing draught from the trolls at Malaka''jin at the base of the Stonetalon Mountains); quest 1511 description (Ken''zigla''s draught to Logmar at Camp Taurajo); quest 6542 description (Darn Talongrip, Kadrak, Ashenvale campaign); quest 1058 description; creature_text 3995 (cauldron); zone_areas area 2539: Jin''Zil, Xen''Zilla, Ken''zigla, Darn Talongrip, Denni''ka, Prisoner of Jin''Zil; CreatureDisplayInfo 4105 (Ken''zigla: troll male model)'),
(40603, 1, 406, 3, 0, 0, 'Camp Aparaje', 'Camp Aparaje was a small tauren village in the southeastern hills of Stonetalon, home to Makaba Flathoof and his daughter Kaya. The Grimtotem fell upon it, led by Grundig Darkcloud of the post further up the path, and killed nearly everyone. Makaba slew all the raiders he could before he barely escaped with his life, and he now waits on the edge of the mountains by the Barrens, sure his daughter was lost in the attack. Grimtotem ruffians and mercenaries still pick through the abandoned camp. For those who know these trails, though, Aparaje remains a landmark on the road home.', 'warcraft.wiki.gg/wiki/Camp_Aparaje (tauren village, Makaba and Kaya lived there, attacked from Grimtotem Post under Grundig Darkcloud); quest 6548 description (Grimtotem raided my village, killed most everyone, I barely escaped); quest 6629 description (Grimtotem Post further up the path to the west); quest 6401 description (we had thought she was lost); quest 6523 description (Kaya: escort me to Camp Aparaje, from there I know my way); zone_areas area 2538: Grimtotem Ruffian 2, Grimtotem Mercenary 1'),
(40604, 1, 406, 4, 0, 0, 'Grimtotem Post', 'Grimtotem Post is a camp of the Grimtotem tribe in the southeastern Stonetalon Mountains, a little further up the path beyond Camp Aparaje. Brutes stand guard and sorcerers work their magic here, and none of them welcomes outsiders. The post is commanded by Grundig Darkcloud, who led the brutal raid that destroyed Aparaje, and his own band of brutes stays close about him. A tauren called Gorehoof the Black roams the camp as well.', 'quest 6629 description (Grundig Darkcloud and his personal band of brutes, led the attack, Grimtotem Post up the path to the west); zone_areas area 2537: Grimtotem Brute 19, Grimtotem Sorcerer 15, Kaya Flathoof 11856, Grundig Darkcloud 11858, Gorehoof the Black 11914; quest 6523 description (Thank you for rescuing me, before they discover I am free); creature_text 11856; CreatureDisplayInfo 10225 (Gorehoof the Black: tauren male model)'),
(40605, 1, 406, 5, 0, 0, 'The Webwinder Path', 'The Webwinder Path is the long road that winds north from the southern valleys through the heart of the mountains, toward Sun Rock Retreat and Windshear Crag. It is named well. Deepmoss spiders, creepers and venomspitters, hunt along its length, and travelers who walk it by night risk the fangs of Besseleth, the great spider of nearby Sishir Canyon, whose bounty notice is posted beside the road. On a rise overlooking the valley that leads into Windshear Crag, the night elf Kaela Shadowspear and her gnome companion Gaxim Rustfizzle have made their camp, plotting against the Venture Company.', 'zone_areas area 1076: Deepmoss Creeper 12, Deepmoss Venomspitter 7, Gaxim Rustfizzle, Kaela Shadowspear, Wanted Poster: Besseleth 177904; quest 6284 description and request text (Besseleth, travelers on Webwinder Path at night); quest 1070 description (Kaela overlooking the valley entering Windshear Crag); quest 1071 description (Windshear Crag to the east); warcraft.wiki.gg/wiki/Kaela_Shadowspear (night elf quest giver, camp southwest of Windshear Crag; not titled Sentinel)'),
(40606, 1, 406, 6, 0, 0, 'Sishir Canyon', 'Sishir Canyon opens west of the Webwinder Path, and it belongs to the spiders. Besseleth and her eight-legged brood have claimed it as their webbed lair, and the canyon floor is thick with deepmoss creepers, webspinners and venomspitters among clusters of eggs. Besseleth is an old predator of these parts who hunts the road by night, and she once caught Maggran Earthbinder of Sun Rock Retreat with her two-foot fang. A goblin trader in Ratchet pays well for deepmoss eggs, now prized for omelettes in Booty Bay, though even he warns that gathering them in Sishir is not for the weak of stomach.', 'Wanted Poster quest 6284 description (Sishir Canyon west of here, Besseleth and her eight-legged children, webbed lair); quest 6284 request and reward text (old predator, two-foot fang, Maggran wounded); zone_areas area 2541: Deepmoss Venomspitter 15, Creeper 9, Webspinner 5, Deepmoss Eggs, Besseleth 11921; quest 1069 description (Mebok Mizzyrix of Ratchet, omelette fad in Booty Bay, Sishir Canyon weak stomach)'),
(40607, 1, 406, 7, 0, 0, 'Boulderslide Ravine', 'Southeast of Sun Rock Retreat, Boulderslide Ravine cuts into the mountains, and at its end a deep cavern runs far beneath the stone. The Gogger kobolds have claimed it, rock keepers, geomancers and stonepounders who mine a rare crystal called resonite with frantic haste and shriek at anyone who reaches for their candles. What drives them to dig so deep is unknown, but the shaman Mor''rogal of Sun Rock senses something evil lurking beneath these mountains.', 'quest 6421 description and reward text (southeast of Sun Rock, deep cave, kobolds frantically mining resonite, earthen magic, earthen created by the titans to shape the land); quest 6481 description (resonite cask houses a slumbering earthen named Goggeroc); zone_areas area 2540: Gogger Rock Keeper, Geomancer, Stonepounder, Resonite Crystal; Resonite Cask 178145; creature_text 11915/11917 (You no take candle)'),
(40608, 1, 406, 8, 0, 0, 'Sun Rock Retreat', 'Sun Rock Retreat is the Horde''s stronghold in the Stonetalon Mountains, a village of tauren and orcs tucked among the peaks south of Mirkfallon Lake and guarded by Stonetalon grunts. Its leader, the veteran Maggran Earthbinder, was sent here by Cairne Bloodhoof himself. Tammra Windfield calls on the Earthmother to help the scorched land grow again, the shaman Mor''rogal senses something evil stirring beneath the mountains, and Tsunaman serves the Tribunal of the Tides, waging the ancient war of water against fire in the Charred Vale. An inn and a wind rider post serve travelers, and at the edge of the village the mage Braelyn Firehand pursues a darker purpose of her own.', 'warcraft.wiki.gg/wiki/Sun_Rock_Retreat (Horde village in central Stonetalon, among peaks south of Mirkfallon Lake, orc and tauren forces); zone_areas area 460: Stonetalon Grunt 14, Maggran, Tammra, Mor''rogal, Tsunaman, Braelyn, Innkeeper Jayka, Tharm; npc_text 5443 (Cairne assigned me to Sun Rock Retreat); quest 6301, 6421, 6393, 1087 descriptions; warcraft.wiki.gg/wiki/Braelyn_Firehand (mage, quest giver at Sun Rock Retreat, removed in 4.0.3a)'),
(40609, 1, 406, 9, 0, 0, 'Mirkfallon Lake', 'Mirkfallon Lake lies north of Sun Rock Retreat, its shores the home of the Pridewing wyverns. Consorts, skyhunters and soarers nest about the water, a great patriarch among them, and a wyvern called Sorrow Wing hunts the shore. Sources in Theramore claim the orcs gather pridewing venom here for their assassins, and the Sentinels of Astranaar have sent fighters south to deny them the source. The lake also holds gentler gifts. Gaea seeds, found nowhere else in the mountains, lie along the water''s edge, and the tauren of Sun Rock gather them in the hope of restoring Stonetalon''s lost forests.', 'zone_areas area 464: Pridewing Wyvern 14, Consort 10, Soarer 2, Skyhunter, Patriarch 4015, Sorrow Wing 5928, Gaea Seed 177926 x12; quest 1134 description and reward text (Shindrell of Astranaar; Theramore sources claim orcs collect pridewing venom near Mirkfallon Lake for assassins); quest 6301 description (Gaea seeds only found in Stonetalon, north of Sun Rock at Mirkfallon Lake near the water''s edge); quest 6381 completion text (restoring Stonetalon to a lush forest)'),
(40610, 1, 406, 10, 0, 0, 'The Charred Vale', 'The Charred Vale in the southwest of the mountains was once a verdant forest. The Venture Company set it ablaze and turned its machines of destruction upon it, and in doing so loosed raging spirits of flame and stone. The treants of the vale seem to have driven the goblins back, but even these guardians were corrupted, some perhaps by the weapons the goblins used in their retreat, and blackened ancients now lumber through the ash. The Bloodfury harpies have since made the vale their stronghold, barring the druids who would heal it, while scorched basilisks and chimaeras hunt the burned slopes. The road south to Desolace runs through it.', 'quest 1844 description (once verdant, now defiled and ashen); quest 1083 description (set the forest aflame, inventions of destruction, released elementals of flame, stone and rage); quest 1084 description (treants drove the Venture Co. back, became corrupt, possibly from weapons used during the retreat); quest 1057 description (Bloodfuries refuse passage to begin regrowth); zone_areas area 465: Bloodfury harpies, Scorched Basilisk, Chimaera Matriarch, Charred/Blackened/Vengeful Ancient, Burning Destroyer, Enraged Stone Spirit; quest 5361 description (Charred Vale, then south into Desolace)'),
(40611, 1, 406, 11, 0, 0, 'Windshear Crag', 'Windshear Crag is a broad valley in the east of the mountains, and it is where the Venture Company''s greed is laid bare. Loggers, deforesters and operators swarm a landscape of stumps and fouled water, and the company''s lumber mill stands south of Cragpool Lake. Two great shredders marked XT:4 and XT:9 fell trees faster than the spirits can bear, and wagons of explosives wait along the trails. Kobold diggers toil for the company here too, and deepmoss spiders lay their eggs under what trees remain. On the crag''s western edge, the goblin Ziz Fizziks, fired when a gnome took charge of the operation, has set up camp and now works against his former employers.', 'warcraft.wiki.gg/wiki/Windshear_Crag (massive logging, stumps and polluted water); zone_areas area 461: Venture Co. Logger 49, Deforester 29, Operator 17, XT:4, XT:9, Explosives Wagons, Deepmoss Eggs, Ziz Fizziks; quest 1068 description (XT:4 and XT:9 felling trees with impossible speed); quest 1079 description (lumber mill south of Cragpool Lake); quest 1069 description (eggs clustered under what trees remain); quest 1090 and 1483 descriptions (Gerenzo took over and fired Ziz; Ziz at the western edge of Windshear Crag); zone_areas area 461: Windshear Digger 46, Overlord 9, Geomancer 5 (kobold models, CreatureDisplayInfo 2153, 511, 163)'),
(40612, 1, 406, 12, 0, 0, 'Windshear Mine', 'The Windshear Mine sits at the far eastern end of Windshear Crag, where the Blackwolf River ends. The Venture Company works it with kobolds in its employ, diggers, geomancers and overlords, and on Gerenzo Wrenchwhistle''s orders large amounts of a strange gold-green ore are being hauled from its depths, for a purpose none of the miners has learned. Among them toils Piznik, once the second most important goblin at the site, sent down to the tunnels when Gerenzo took over. The company keeps some of its letters here, deep inside.', 'quest 1080 description (Windshear Mine at the east end of Windshear Crag, Venture Co. letters); warcraft.wiki.gg/wiki/Windshear_Mine (Venture Company employed kobolds to mine; at the end of the Blackwolf River); quest 1090 description (Piznik second most important, sent down to the mines, gold-green ore, gather information for Ziz); DB: Windshear Digger, Geomancer, Overlord; Piznik 4276 and Venture Co. Documents 19603 at the mine near 960..990,-260..-390; CreatureDisplayInfo 2153, 163, 511 (Windshear Digger, Geomancer, Overlord: kobold models); 7157 (Piznik: goblin); WMOAreaTable rows 19186 to 19210 (WMO 996, area 2160)'),
(40613, 1, 406, 13, 0, 0, 'Cragpool Lake', 'Cragpool Lake lies in the north of Windshear Crag, and the Venture Company has crowded its shores. Oil spills slick the water, while engineers, machine smiths and builders keep the company''s machines running along the banks, and a goblin named Nizzik sells Venture armor to any customer with coin. Far above the lake, up beside the great water wheel, Gerenzo Wrenchwhistle keeps watch over the entire site from his high platform. From the lake the Blackwolf River runs out through the crag, and travelers bound for Stonetalon Peak skirt the water before turning north up the steep slopes.', 'zone_areas area 463: Oil Spill, Venture Co. Engineer, Machine Smith, Builder, Logger, Nizzik <Venture Armor Salesman> 4085 (faction 35), Gerenzo Wrenchwhistle 4202; quest 1096 description (northeast of here, far above Cragpool Lake, near the water wheel, Gerenzo watches over the entire site); quest 1079 description (lumber mill south of Cragpool Lake); quest 1056 description (southwest past Cragpool Lake and then north up the steep slope to Stonetalon Peak); warcraft.wiki.gg/wiki/Blackwolf_River (runs through Windshear Crag from Cragpool Lake); creature positions: Gerenzo 1606,97 and Nizzik 1608,184 lie north of Ziz (878,365) and the mine (986,-390)'),
(40614, 1, 406, 14, 0, 0, 'Blackwolf River', 'The Blackwolf River runs out of Cragpool Lake and down through Windshear Crag to the mine at its far end, and its waters have been fouled by the Venture Company''s logging of the valley. The company''s crews have stripped the banks bare. Loggers, deforesters and operators work the riverside, kobold geomancers among them, oil leaks into the current, and a wagon of explosives waits nearby. Two hard bosses drive the work here: Foreman Rigger, a human, and Taskmaster Whipfang, a gnoll.', 'zone_areas area 636: Venture Co. Logger 14, Deforester 7, Operator 5, Oil Spill 3, Explosives Wagon, Foreman Rigger 5931, Taskmaster Whipfang 5932; warcraft.wiki.gg/wiki/Windshear_Mine (mine at the end of the Blackwolf River); warcraft.wiki.gg/wiki/Blackwolf_River (from Cragpool Lake through Windshear Crag; heavily polluted by Venture Company deforestation); CreatureDisplayInfo 4600 (Rigger: human male), 487 (Whipfang: gnoll)'),
(40615, 1, 406, 15, 0, 0, 'The Talondeep Path', 'The Talondeep Path is a long tunnel bored through the mountains, joining Windshear Crag to southern Ashenvale not far from Mystral Lake. It is a main road between Stonetalon and the forest: night elves bound for Stonetalon Peak travel it, and Horde caravans running between the mountains and Splintertree Post depend on it, so that trouble at Mystral Lake can bring them to a standstill. Deepmoss spiders lurk in its shadows and lay their eggs in the dark. Near its Stonetalon mouth waits a tauren named Braug Dimspirit.', 'quest 1056 description (tunnel near Mystral Lake leads to Windshear Crag); quest 25 description (transports between Ashenvale and Stonetalon via Talondeep Path); zone_areas area 1277: Deepmoss Webspinner, Braug Dimspirit 4489; quest 1152 description and reward text (Braug, shaman of great wisdom, near the tunnel; Dorn; goblins rape the land, night elves point fingers at the younger races); npc_text 5820 (question on the Aspects); quest 25 description (caravans between Splintertree Post and Stonetalon at a standstill); zone_areas area 1277: Deepmoss Eggs 19541, 19542'),
(40616, 1, 406, 16, 0, 0, 'Stonetalon Peak', 'Stonetalon Peak crowns the far northwest of the mountains, a high forested valley that local peoples have long held sacred. Ruins of an ancient temple of Queen Azshara still stand here. The night elves keep a small outpost here with an inn and a hippogryph roost, where Keeper Albagorm watches over the land, and the Sons and Daughters of Cenarius and their botanists tend the woods, while sap beasts, twilight runners and fey dragons roam among the trees. In the Third War, Jaina Proudmoore''s expedition camped by the caverns of the peak, and Thrall came there too in search of the Oracle.', 'warcraft.wiki.gg/wiki/Stonetalon_Peak (northwestern end, forested valley, sacred, temple of Queen Azshara, Third War Jaina and Thrall at the caverns, druids maintain it); quest 1088 description and request text (our ancient temple of Azshara, sacred ruins; they spirited Ordanus away from the peak); quest 1087 description (ilk of Cenarius and kaldorei druids at the peak); zone_areas area 467: Keeper Albagorm, Innkeeper Faralia, Teloren hippogryph master, Son/Daughter of Cenarius, Cenarion Botanist, Sap Beast, Twilight Runner, Fey Dragon, Wily Fey Dragon'),
(40617, 1, 406, 17, 0, 0, 'The Talon Den', 'The Talon Den is a barrow den built by the druids on Stonetalon Peak. Cenarion druids and caretakers walk its halls beside the Mirkfallon dryads, and an ancient keeper of the grove, Gatekeeper Kordurus, stands among them. Caches of the druids stand here and there about the den, and the dryad Rynthariel bears the title of its Keymaster. A night elf called Brother Ravenoak prowls its depths, and somewhere deeper within lies a hoard the druids guard closely.', 'warcraft.wiki.gg/wiki/Talon_Den (barrow den on Stonetalon Peak; dryads, caretakers, keepers; Kordurus, Rynthariel, Ravenoak); quest 1089 description (the druids built the Talon Den, powerful items, complex scheme, Gatekeeper''s Key in a lantern at the entrance, caches, hoard in a central area); quest 1089 completion text (three keyholes); zone_areas area 468: Cenarion Druid 16, Cenarion Caretaker 7, Mirkfallon Dryad 6, Gatekeeper Kordurus, Rynthariel the Keymaster, Brother Ravenoak, Gatekeeper''s Hold, Druids'' Cache, Barrow Cache; quest 3514 description (scheming dryad Rynthariel, Keymaster); CreatureDisplayInfo 2432 (Kordurus: keeper of the grove model), 4599 (Ravenoak: night elf male); gameobject 19599 Talon Den Hoard at 2562,1947 (posarea 467, past the den''s caches)'),
(40618, 2, 406, 1, 2, 0, 'Seereth Stonebreak', 'Seereth Stonebreak is a promising shaman of the Horde, sent to Stonetalon when the land cried out. She camps where the road from the Crossroads meets the mountains, near the Greatwood Vale, and to her the spirit of Stonetalon weeps from its peaks, its rivers and its severed, dying trees. Shamans can hear the pleas of such spirits because their magic is kin to the natural magic of the druids, she says, though many of the whispers are lost to her. She asks for help against the Venture Company, in the one language the goblins understand best: violence.', 'quest 1061 description (promising shaman of the Horde, sent to Stonetalon, camped near the Greatwood Vale); quest_greeting 4049 (spirit of Stonetalon weeps, peaks, rivers, severed dying trees); quest 1068 description and reward text (relation between shamanic and druidic magic, whisperings lost, vision of XT:4 and XT:9; fears what lies ahead); creature_text 4049 (I fear we may never soothe them); quest 1062 description (show them in the language they best understand, violence)'),
(40619, 2, 406, 2, 2, 0, 'Maggran Earthbinder', 'Maggran Earthbinder leads Sun Rock Retreat, an old tauren warrior who admits that age and countless battles have hardened his skin and his soul. He believes that is why Cairne Bloodhoof gave him this post, where gentle winds and warm sun ease his pain. Maggran takes the tauren duty as protectors of the land seriously. He holds the Bloodfury harpies of the Charred Vale to be the source of the harpies spreading across Kalimdor and wants their queen, Bloodfury Ripper, dead, and he has put a bounty on the spider Besseleth, whose fang once wounded him.', 'npc_text 5443 (age and battles hardened skin and soul; Cairne assigned me; gentle winds and warm sun); quest 6282 description (tauren take pride as protector of these lands; Bloodfuries source of increasing harpies in Kalimdor); quest 6283 description and reward text (Bloodfury Ripper all but a queen; already I feel the anger leave me); quest 6284 request and reward text (bounty, Maggran wounded by Besseleth''s fang)'),
(40620, 2, 406, 3, 2, 0, 'Witch Doctor Jin''Zil', 'Jin''Zil is a troll witch doctor who lives in a cave at Malaka''jin, among bubbling cauldrons, and he greets visitors with the cry that the spirits are restless. His temper is gleeful and cruel. Three night elves sit caged near his camp, and for these tree-hugging friends, as he calls them, he means to brew what he calls forest magic, out of sap from Stonetalon Peak, the whiskers of twilight runners, a fey dragon''s scale and as many courser eyes as he can get. One can never have enough eyes, he says.', 'quest 1060 description and reward text (old friend of Darsok; letter; last of the Bloodfeathers; Rokhan went with that crazy mok''nathal to kill her older sister); barrens.json Serena Bloodfeather entry (Rexxar and Rokhan killed her sister); quest 1058 description, request and reward text (three cages, forest magic ingredients, eyes); creature_text 3995 (cauldron; feel the magic seep into the cave, my little elves); quest_greeting 3995 (The spirits are restless!); quest 1058 description (tree-hugging friends; can never have enough eyes)'),
(40621, 2, 406, 4, 2, 0, 'Braelyn Firehand', 'Braelyn Firehand is a mage who camps at Sun Rock Retreat, and she despises these mountains. The druids of Stonetalon Peak and the kin of Cenarius stifle the flow of magic far beyond their forests, and here, she says, channeling a spell is like drawing water from a well with a bucket full of holes. She longs to return to Jaedenar and exult in the flow of magic there, but her master will not let her go until her work is done, and she seeks out those who love the night elves as little as she does.', 'quest 1087 description and request text (hatred, stifle the flow of magic, master in Jaedenar, bucket full of holes); quest 1088 request and reward text (master bade me to the peak, sacred ruins of our ancient temple of Azshara; I knew Ordanus once, held himself above even the Highborne); zone_areas area 460: Braelyn Firehand; quest 1087 reward text (power so sweet; kaldorei foolish to spurn the gifts; pale mockery without its burning embrace); warcraft.wiki.gg/wiki/Braelyn_Firehand (mage; at Sun Rock Retreat)'),
(40622, 2, 406, 5, 1, 0, 'Keeper Albagorm', 'Keeper Albagorm watches over Stonetalon Peak for the night elves, and he mourns what greed has done to these sacred hills. When the forest spirits whisper to Faldreas Goeth''Shael in Astranaar, it is to Albagorm that the brave are sent, through the Talondeep Path and up the steep slopes past Cragpool Lake. His great hope is the Charred Vale. He means to restore it to the lush forest it once was, but first the Bloodfury harpies who bar the druids from the vale must be driven out.', 'quest 1056 description and reward text (Faldreas has listened to the forest spirits; route via Talondeep Path, Cragpool Lake, steep slope); quest 1057 description and request text (protector of the forest spirits, greed destroyed sacred hills, Bloodfuries refuse passage, restore lush forest); quest 1059 description (Falfindel Waywarder can call forth great forest spirits); zone_areas area 467: Keeper Albagorm'),
(40623, 2, 406, 6, 1, 0, 'Kaela Shadowspear', 'Kaela Shadowspear is a night elf of Ashenvale, sent to Stonetalon by Sentinel Raene Wolfrunner to learn what was happening to the land, with a gnome mage assigned to accompany her. From her camp above the road into Windshear Crag she has spent most of her days fighting the Venture Company''s destruction. That a night elf and a gnome must work together shows how grave things are, she admits, but she asks others not to judge Gaxim too quickly. She still misses her homeland and her friend Tara Thenysil in Astranaar, and the first time she saw the Charred Vale, she nearly wept.', 'quest 1070 description and reward text (Sentinel Wolfrunner sent my friend Kaela; gnome mage along; how I miss her, my homeland and friends); quest 1085 description (night elf and gnome working together; most of my time putting an end to the destruction; do not judge Gaxim prematurely); quest 1083 request text (first time I saw the Charred Vale I almost wept); quest 1082 description (Tara Thenysil in Astranaar); warcraft.wiki.gg/wiki/Kaela_Shadowspear (night elf, affiliation Darnassus, not titled Sentinel)'),
(40624, 2, 406, 7, 1, 0, 'Gaxim Rustfizzle', 'Gaxim Rustfizzle is a gnome of the Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences, and he holds it as his duty to prove to the night elves that magic, mixtures and mechanisms together can save their forests. Swearing off magic entirely, he insists, will help no one. At Kaela Shadowspear''s side he wages a cheerful war of explosions on the Venture Company, herding goblin crews with carefully placed detonations along the mountains'' edges, and he promises that his best invention, a blast that doubles as a distraction, is still to come.', 'quest 1071 description and reward text (Enlightened Assembly; my duty to show the night elves; high explosives to herd goblins along the mountains'' edges); quest 1085 reward text (swearing off magic completely won''t help the night elves); quest 1072 to 1074 (Lomac Gearstrip in Tinker Town, NG-5); quest 1075 to 1077 (Collin Mauren, mage quarter, remote detonation scroll); quest_greeting 4077 (explosives that damage the Venture Co.''s operations but also cause a distraction; I''ll tell you more soon)'),
(40625, 2, 406, 8, 0, 0, 'Ziz Fizziks', 'Ziz Fizziks was once an engineer of the Venture Company in Windshear Crag, until the company hired a gnome. The goblin was so appalled that he begged Sputtervalve of the Tinkers'' Union in Ratchet for a new job, and when Gerenzo Wrenchwhistle took over the site, Ziz was thrown out. Now he camps on the crag''s western edge, eager to prove his loyalty to his new boss, though he admits a goblin''s honor is only worth so much, and that Sputtervalve is the cruelest slave driver he has ever met. Gerenzo, he says, wants him dead on sight.', 'quest 1483 description (Gerenzo hired, Ziz taken aback, pleaded with Sputtervalve for new employment, western edge of Windshear Crag); quest 1090 description (Gerenzo fired my boss Ziz; Ziz told me to stay and gather information); quest 1092 reward text (I did the right thing by telling Piznik to stay behind); quest 1093 description and request text (kicked out; Sputtervalve hired me; goblin''s honor); quest 1095 and 1096 reward text (no objections to eliminating Gerenzo; Tinkers'' Union workshops in Gadgetzan or Undermine); quest 1483 reward text (Sputtervalve the cruelest of them all); quest 1093 description (Gerenzo wants me dead on sight)'),
(40626, 2, 406, 9, 0, 0, 'Gerenzo Wrenchwhistle', 'Gerenzo Wrenchwhistle is a gnome, and he is not easy to look upon: his flesh seems to rot away, gears and metal are grafted onto his body, and some of his limbs have been replaced with machines. He keeps his post far above Cragpool Lake, on a high platform near the great water wheel, where the whole of the Venture Company''s works in Windshear Crag lies open below him. Company machine smiths and builders labor on the heights around him, and he is no friend to anyone of the Alliance or the Horde who climbs up to meet him.', 'quest 1096 description (flesh rotting, metal and gears grafted, limbs replaced; far above Cragpool Lake near the water wheel; watches over the entire site); creatures near 4202 (1606,97): Venture Co. Machine Smith 3993, Venture Co. Builder 4070; quest 1483 description (outfit hired Gerenzo, a gnome; Ziz taken aback); quest 1093 description (enormous woodcutting machine; Gerenzo wants Ziz dead); quest 1095 description and reward text (trade princes disapprove of Razdunk consorting with Gerenzo; head engineer in Gnomeregan, secret project exploded in their faces); warcraft.wiki.gg/wiki/Gerenzo_Wrenchwhistle (leper gnome, built the Super Reaper 6000); creature_template 4202 faction 47 (hostile to both)'),
(40627, 2, 406, 10, 2, 0, 'Rynthariel the Keymaster', 'Rynthariel the Keymaster is a dryad of the Talon Den, the druids'' barrow den on Stonetalon Peak, and her title names her the keeper of its keys. She keeps her place in its halls near Gatekeeper Kordurus, an ancient keeper of the grove, with Cenarion druids and caretakers close by, and Mirkfallon dryads, her own kind, walk the den as well. She stands with the night elves, and any warrior of the Horde who comes into the den will find her ready to fight.', 'quest 3514 description and reward text (scroll from that scheming dryad Rynthariel, Keymaster of the Talon Den; kill her and put up a Horde flag; fewer Alliance runners in the Barrens); quest 3513 (The Runed Scroll, dropped by Aean Swiftriver 5797, taken to the outpost near the Ashenvale border); creature_template 8518 faction 124 (friendly to the Alliance); zone_areas area 468: Rynthariel the Keymaster; creatures near 8518 (2366,1795): Gatekeeper Kordurus 4409, Cenarion Druid 4052, Cenarion Caretaker 4050; CreatureDisplayInfo 2432 (Kordurus: keeper of the grove model)'),
(40628, 3, 406, 1, 2, 0, 'The Spirits of Stonetalon', 'The spirits of the Stonetalon Mountains are angered, for the goblins of the Venture Company and their servants are cutting and burning the forests, and the spirits are nearly blind with pain and rage. The land cried out, and in Orgrimmar the far seer Zor Lonetree heard. He sent help west from the Crossroads to the promising shaman Seereth Stonebreak, who had reported deforestation on a massive scale. She asks first for the answer the goblins understand best: violence, carried northwest beyond the Greatwood Vale to the Venture Company''s crews in Windshear Crag.', 'quest 1061 description (spirits angered, land cried out, those who listen have heard, Seereth reports massive deforestation); quest 1062 description and reward text (show them in the language they understand, violence; wisdom of tauren elders); quest 1068 description and reward text (vision of XT:4 and XT:9, soothed many spirits); quest 1063 description (consult the tauren elders, only knows Magatha, very old, Elder Rise); orgrimmar.json Valley of Wisdom (Zor Lonetree, elder far seer)'),
(40629, 3, 406, 2, 2, 0, 'Cenarius'' Legacy', 'Braelyn Firehand came to Stonetalon at the bidding of her master in Jaedenar, and she hates the land with all her heart. The kin of Cenarius and the kaldorei druids at the peak use their powers to stifle the flow of magic, even this far south of their beloved forests, and she will not be allowed home until her work is done. She asks for help from those who love the night elves as little as she does. First, the flow of magic must be restored, and for that the Sons and Daughters of Cenarius and their botanists on the peak must die.', 'quest 1087 description and reward text (master in Jaedenar; kill Sons and Daughters of Cenarius and botanists; power so sweet, the rushing flood); quest 1088 description, request and reward text (true sight; Raynewood, crossroads, eldest sons of the forest god; spirited away from the peak; master bade me to the peak; sacred ruins of our ancient temple of Azshara; I knew Ordanus once); quest 1089 description (extract some details from one of them; Gatekeeper''s Key in a lantern, caches, hoard); ashenvale.json Raynewood Retreat entry (Ordanus hiding at the top of the tree)'),
(40630, 3, 406, 3, 1, 0, 'On Guard in Stonetalon', 'Stonetalon is a land plagued by the Venture Company and other enemies of the night elves, and Sentinel Raene Wolfrunner sent Kaela Shadowspear there to learn what was happening to it. Kaela''s friend, Sentinel Tara Thenysil of Astranaar, has heard nothing from her since, and the news that the Alliance sent a gnome mage along only deepens her worry: to her it is a sure sign of trouble. She asks a traveler bound for the mountains to find Kaela and bring back word.', 'quest 1070 description (Thenysil, Kaela, gnome mage); quest 1085 description; quest 1071 description and reward text; quests 1072, 1073, 1074 (Lomac Gearstrip, NG-5); quests 1075, 1076, 1077 (Collin Mauren, dust devil debris, scroll of messaging, remote explosive); quests 1079 and 1080 (plans from the lumber mill, letters from Windshear Mine); quest 1091 (Kaela''s Update); quest 1082 description (Gaxim and I are alive, well on our way to stopping the Venture Co. and healing the lands); quest 1081 description and reward text (Tyrande, gift of appreciation)'),
(40631, 3, 406, 4, 1, 0, 'Reclaiming the Charred Vale', 'In Astranaar, Faldreas Goeth''Shael listens to the spirits of the forest, and they told him of one brave enough to travel. He sends that traveler south through the Talondeep Path, across the ravaged Windshear Crag and up the steep slopes to Stonetalon Peak, where Keeper Albagorm waits. The keeper''s grief is for the Charred Vale, once forest, now ash, set afire by a greedy mechanized army of industrialists. The druids wish to begin its regrowth, but the Bloodfury harpies who have settled the burned vale will not let them pass, and Albagorm wants them driven out.', 'quest 1056 description and reward text (forest spirits tell me you are brave; route; Faldreas has listened to the forest spirits); quest 1057 description, request and reward text (set afire by the greedy mechanized army of industrialists; Bloodfuries refuse passage; restore the lush forest); quest 1059 description and reward text (Bloodfuries subdued but will regroup; Falfindel Waywarder at the border of Thousand Needles and Feralas, can call forth great forest spirits)'),
(40632, 3, 406, 5, 2, 0, 'The Seeds of Gaea', 'At Sun Rock Retreat, Tammra Windfield grieves for a land wrecked by industrial greed and endless war, and she holds that only the blessings of the Earthmother can cure such an injury. Her hope lies in the Gaea seed, found nowhere else but along the shores of Mirkfallon Lake, north of the retreat near the water''s edge. She means to imbue the seeds with shamanic power to speed their growth, so that the cycle of rebirth may begin to replenish the land.', 'quest 6301 description and reward text (industrial greed and continuous war; blessings of the Earthmother; Gaea seeds only found at Mirkfallon Lake; imbue with shamanistic power; Tammra begins to chant); quest 6381 description, request and reward text (plant at the center of the destruction in the Charred Vale; harpies and fire elementals; resist corruption, foothold for other life; Venture Co. will pack up, fire spirits calm, harpies pushed out; then truly at peace); zone_areas: Gaea Seed 177926 at Mirkfallon Lake, Gaea Dirt Mound 177929 in the Charred Vale'),
(40633, 3, 406, 6, 0, 0, 'Gerenzo''s Orders', 'When the Venture Company hired the gnome Gerenzo Wrenchwhistle to run its Windshear Crag outfit, the goblin engineer Ziz Fizziks was so appalled that he begged Sputtervalve of the Tinkers'' Union in Ratchet for a new job, and he was soon thrown out of the company. Sputtervalve, who says the Venture Company stole many of the best goblin minds, is glad of a chance to steal some back. He set Ziz to work from a camp on the crag''s western edge, where the goblin is eager to learn what Gerenzo is planning and to prove his loyalty to his new boss.', 'quest 1483 description and reward text (Sputtervalve; Gerenzo hired; Ziz pleaded for new employment); quests 1090 and 1092 (Piznik, ore sample, watch for patrols, sneak out; engineers in Undermine; keep a piece for myself); creature_text 4276 (escort lines; 4004''s are never said); quests 1093 and 1094 (Super Reaper 6000 blueprints on an operator; sealed envelope with internal documents to Sputtervalve at Ratchet); quest 1095 description and reward text (trade princes, Razdunk, Riddlevox; Gerenzo head engineer in Gnomeregan); quest 1096 description and request text (above Cragpool Lake; mechanical arm as proof); quest 1483 description (Venture Company stole many of the best goblin minds; steal some back)'),
(40634, 3, 406, 7, 2, 0, 'The Fall of Camp Aparaje', 'Makaba Flathoof waits at the edge of the mountains by the Barrens, one of the very few who lived through the day the Grimtotem came to Camp Aparaje. The raiders killed most everyone in the village. Makaba killed all he could before he fled with his life, and he will never forget what the Grimtotem did there. Now he asks only that more of them die, starting with the ruffians and mercenaries who prowl the woods just to the west. Among the dead, he believes, was his own daughter Kaya.', 'quest 6548 description and reward text (Grimtotem raided my village, killed most everyone, I killed all I could, barely escaped; just to the west); quest 6629 description (Grundig Darkcloud and his personal band of brutes, led the attack, Grimtotem Post); quest 6523 description (thank you for rescuing me, escort me to Camp Aparaje, from there I know my way, father Makaba); creature_text 11856 (Let''s go before they find out I''m free; Look out, we''re under attack; I know my way back from here); quest 6401 description and reward text (Kaya''s aunt Tammra at Sun Rock; we had thought she was lost; my niece Kaya is alive)'),
(40635, 3, 406, 8, 2, 0, 'Earthen Arise', 'The shaman Mor''rogal of Sun Rock Retreat can feel a tension in the air of Stonetalon, a sense that something evil lurks beneath the mountains. Southeast of the retreat, in a deep cave in Boulderslide Ravine, the Gogger kobolds are mining a rare crystal called resonite in a frenzy, and Mor''rogal wants samples of the ore and word of what lies at the bottom of the cave. He half remembers some legend tied to resonite but cannot place it, and he hopes the depths will reveal what the kobolds intend.', 'quest 6421 description, request and reward text (tension, evil under the mountains, southeast cave, kobolds frantically mining Resonite, legend; trace of Earthen magic, created by the Titans to create the land, enchant the samples); quest 6481 description, request and reward text (Resonite cask houses slumbering Earthen Goggeroc; enchanted crystal to smash it; weak from slumber; what an Earthen would mean to Kalimdor); zone_areas area 2540 and Resonite Cask 178145');
INSERT INTO `mod_lore_codex_part` (`Entry`, `Part`, `MinState`, `MaxState`, `Body`, `Sources`) VALUES
(40604, 1, 0, 255, 'Not all of Aparaje''s people died in that raid. Makaba Flathoof''s daughter Kaya was taken alive and held captive here at the post. Once freed, she wants only to slip away to the ruins of her village before her captors discover she is gone, for from there she knows the way home to her father.', 'quest 6523 description (thank you for rescuing me; leave before they discover I am free; escort me to Camp Aparaje, from there I know my way; my father Makaba); zone_areas area 2537: Kaya Flathoof 11856'),
(40607, 1, 0, 255, 'The cave gives up its secret at the bottom, where a resonite cask stands. The crystals carry a trace of earthen magic, and Mor''rogal believes the kobolds have dug deep enough to uncover an earthen, one of the beings the titans made to shape the very land. Such a thing in kobold hands is a threat that cannot be ignored.', 'quest 6421 reward text (Resonite crystals have a trace of Earthen magic; kobolds must have dug deep uncovering an Earthen; created by the Titans to create the land; a threat that cannot be ignored); quest 6421 objective (explore deep into the cave) and 6481 description (the Resonite cask you have found in that cave)'),
(40612, 1, 0, 255, 'Piznik never truly left his old boss. Ziz Fizziks told him to stay behind and learn what Gerenzo was planning, and he dug out a sample of the ore while vermin and tunnel rats swarmed out of the dark to stop him. After that much noise, he knew the company''s higher ups would not take kindly to seeing him again, and he meant to slip out of the mine and join Ziz.', 'quest 1090 description and reward text (Ziz told me to stay and gather information; watch for patrols; drawn far too much attention); quest 1092 description (offered on turning in 1090: I''ll sneak out and meet with Ziz); smart_scripts 427600 (Piznik''s mining event summons Windshear Vermin 3998 and Windshear Tunnel Rat 4001)'),
(40616, 1, 0, 255, 'The peak once hid a greater secret. The druids kept Keeper Ordanus, one of the eldest sons of the forest god Cenarius, concealed here, and when he was hunted they spirited him away to a great tree in Ashenvale before the one who sought him could find him.', 'quest 1088 description (one of the eldest sons of the forest god; at the top of a great tree in Ashenvale; spirited him away from the peak before I could find him)'),
(40617, 1, 0, 255, 'The druids keep many items of power in the den, and to guard them they devised an intricate scheme. A gatekeeper''s key hidden in a small lantern at the entrance opens the caches scattered through the halls, and what lies in those caches unseals the great hoard deeper within.', 'quest 1089 description (powerful items; complex scheme; Gatekeeper''s Key in a small lantern at the entrance; caches; hoard in one of the central areas)'),
(40618, 1, 0, 255, 'Striking at the loggers was a good first move, but no more than that. The spirits of Stonetalon still rage, Seereth says, and she fears they may never be soothed. In the end, she believes, it may take the wisdom of the tauren elders to calm them.', 'quest 1062 reward text (wisdom of tauren elders; ridding the Venture Company of its personnel a good first move); creature_text 4049 (said on 1062 reward, smart_scripts 4049: The spirits of Stonetalon still rage; I fear we may never soothe them)'),
(40618, 2, 0, 255, 'One vision did come clear to her: two man-shaped machines marked XT:4 and XT:9, felling trees in Windshear Crag with impossible speed. Their destruction soothed many of the spirits. Still she hopes the Venture Company will now leave the mountains, for if it does not, she fears all that this place has suffered will pale beside what lies ahead.', 'quest 1068 description and reward text'),
(40619, 1, 0, 255, 'Besseleth''s death brought him no grief. Rubbing the wound her fang left, Maggran called her an old predator of these parts he would not miss, and hoped that many more travelers would now come to Sun Rock Retreat without fearing what lurks in the dark.', 'quest 6284 reward text (old predator; I will miss her not; Maggran rubs the wound; many more will travel to Sun Rock Retreat without fearing what lurks in the dark)'),
(40619, 2, 0, 255, 'With the Ripper slain, Maggran feels his anger begin to leave him. Knowing that evil moved near his land kept his thoughts busy, and now they fall silent. Perhaps, he says, that is a good thing, for now he can turn to the good, as all tauren should.', 'quest 6283 reward text'),
(40620, 1, 0, 255, 'A letter from Darsok Swiftdagger of the Crossroads reached him after many years of silence. Jin''Zil is pleased to learn that the last of the Bloodfeathers is dead, for he still remembers the day his friend Rokhan went off with that crazy mok''nathal Rexxar to kill Serena Bloodfeather''s elder sister. Ah, to be young again, he sighs.', 'quest 1060 description and reward text (old friend of Darsok; not heard from him in many years; last of the Bloodfeathers dead; Rokhan went with that crazy mok''nathal to kill her older sister); barrens.json Serena Bloodfeather entry (Rexxar killed her sister)'),
(40620, 2, 0, 255, 'The forest magic proves to be no gift. Jin''Zil drops the animal parts into his bubbling cauldron and bids his little elves feel the magic seep into the cave, and under his curse the caged prisoners fall dead, one and all. So much for the power of nature, he cackles.', 'smart_scripts 3995 and 399500 (on 1058 reward: say lines 0 and 1, cross cast Jin''Zil''s Curse 6584, kill every Prisoner of Jin''Zil 4072 within 30 yards (target type 9, range 0 to 30), say line 2); creature 4072: all three spawns stand within 15 yards of Jin''Zil; creature_text 3995 (drops the animal parts into the bubbling cauldron; feel the magic seep into the cave, my little elves; so much for the power of nature)'),
(40621, 1, 0, 255, 'When the flow of magic returns and she feels it rush back into her, Braelyn exults in it. To her the kaldorei are fools to spurn the gifts of this world and reject magic as it flows singing through the veins, for life without its burning embrace is a pale mockery.', 'quest 1087 reward text'),
(40621, 2, 0, 255, 'Her work began at the peak. Her master sent her there, among the sacred ruins of what she calls her own people''s ancient temple of Azshara, expecting her only to lay waste to the night elves who crawled over them. She knew Keeper Ordanus long ago, she says, and he held himself above even the Highborne.', 'quest 1088 request and reward text (master bade me to the peak; sacred ruins of our ancient temple of Azshara; I knew Ordanus once, long ago; above even the Highborne)'),
(40622, 1, 0, 255, 'The harpies have suffered a great loss, and the true work of restoring the land may begin. Albagorm knows the Bloodfuries will regroup soon enough, so he looks far to the south, to a druid who can call forth great forest spirits to aid the vale''s reclamation: Falfindel Waywarder, at the edge of Feralas.', 'quest 1057 reward text (Bloodfuries suffered a great loss; true work of restoring the land can begin); quest 1059 description (offered on turning in 1057; will regroup; Falfindel Waywarder can call forth great forest spirits)'),
(40624, 1, 0, 255, 'His friends reach far. His old colleague Lomac Gearstrip of Tinker Town, the only one who can make the volatile Nitromirglyceronium, brewed him a batch, and Collin Mauren of Stormwind''s mage quarter impressed a messaging spell upon a scroll. Together they make a remote explosive, and wagons of dynamite become Gaxim''s perfect distraction.', 'quest 1072 description (only Lomac Gearstrip can make NG-5; Tinker Town); quest 1074 reward text (NG-5 ignites the wagons of dynamite; perfect distraction); quests 1075 to 1077 (Collin Mauren, mage quarter, messaging spell scroll, remote explosive); quest_template_addon: 1079 and 1080 follow 1074 and 1077 (exclusive group -1074), so accepting either means both are done'),
(40625, 1, 0, 255, 'Ziz left a man behind when he went. He had told Piznik to stay in the mine and gather what he could, and when a sample of Gerenzo''s ore came out he was sure he had done right. He meant to send it to the engineers in Undermine, keeping a little piece for himself, since what they did not know would not hurt them.', 'quest 1092 reward text; quest 1090 description (Ziz told me to stay here and gather information)'),
(40625, 2, 0, 255, 'Orders to eliminate Gerenzo were a prospect Ziz had no objection to. With the gnome out of commission, he turned the mechanical arm over and wondered why anyone would cut off an arm to replace it with that, when one could keep both and add a third. He hopes it will earn him a post in a Tinkers'' Union workshop in Gadgetzan, or even Undermine.', 'quest 1095 reward text (no objections to eliminating Gerenzo); quest 1096 reward text (mechanical arm; keep both arms and add a third; Gerenzo''s out of commission; workshops in Gadgetzan or Undermine)'),
(40626, 1, 0, 255, 'Gerenzo is the gnome the Venture Company hired for its outfit in Windshear Crag, and the goblin engineer Ziz Fizziks, appalled that a goblin company would hire a gnome, was thrown out. The outfit has since built an enormous woodcutting machine, the Super Reaper 6000, and Gerenzo, Ziz says, wants him dead on sight.', 'quest 1483 description (the outfit hired Gerenzo, a gnome; Ziz so taken aback he sought new employment); quest 1093 description (goblin company hiring a gnome; kicked out; they built some enormous woodcutting machine; Gerenzo wants me dead on sight), offered on turning in 1483 (RewardNextQuest 1093)'),
(40626, 2, 0, 255, 'Not everyone in Undermine approves of him. The trade princes frown on Razdunk''s dealings with the gnome, and Director Riddlevox has passed down word that Gerenzo must be removed. His past is no comfort to the goblins either: he was once one of the head engineers of Gnomeregan, working on its secret project, which by all reports exploded in its makers'' faces.', 'quest 1095 description and reward text (trade princes disapprove of Razdunk consorting with Gerenzo; Riddlevox; head engineer in Gnomeregan, secret project, a failure, exploded in their faces)'),
(40626, 3, 0, 255, 'Gerenzo Wrenchwhistle falls at last on his high platform above Cragpool Lake, his grafted metal no match for those who climbed up to face him, and the heights by the great water wheel no longer have their watcher looking down over the Venture Company''s works.', 'creature 4202 on the platform above Cragpool Lake; quest 1096 description and reward text'),
(40627, 1, 0, 255, 'To the Horde she is the leader of the Talon Den, and she sends Alliance runners across Horde lands in the Barrens. When one of her scrolls was taken from a fallen courier and carried to Kadrak at the watch tower in the north, the Horde took it as an insult. Kadrak called her a scheming dryad and demanded more than her death: a Horde banner raised inside the den itself, so that the night elves would think twice before sending another runner through Horde territory.', 'quest 3514 description and objective (scroll from that scheming dryad Rynthariel, Keymaster of the Talon Den; messenger looted; will not tolerate her outrunners; kill her and put up a Horde flag; kill the leader of the Talon Den); quest 3513 (The Runed Scroll, taken to the northern guard tower), the Barrens'' quest'),
(40627, 2, 0, 255, 'Rynthariel the Keymaster, the dryad who held the keys of the Talon Den, falls at last in its halls on Stonetalon Peak, struck down by the Horde amid the barrow where she kept her watch.', 'zone_areas area 468: Rynthariel the Keymaster; quest 3514 objective (kill the leader of the Talon Den)'),
(40627, 3, 0, 255, 'Kadrak counts her death a major step. The night elves of the den will be slow to regroup, he reckons, and they will think again before sending another runner through Horde territory, so the Barrens should see fewer Alliance messengers from now on.', 'quest 3514 reward text (ridding the Den of Rynthariel is a major step; slow to regroup; less Alliance runners in the Barrens; they will think again)'),
(40628, 1, 0, 255, 'Loggers fell in Windshear Crag, a good first move against the Venture Company, but no more than that. The spirits still raged, and Seereth feared they might never be soothed. In the end, she thought, it might take the wisdom of the tauren elders to calm them.', 'quest 1062 reward text; creature_text 4049 (said on 1062 reward)'),
(40628, 2, 0, 255, 'Then a vision came to Seereth of two man-shaped machines marked XT:4 and XT:9, cutting down trees with impossible speed. These too were destroyed, soothing many of the spirits, but she warned that if the Venture Company stayed, all that Stonetalon had suffered would pale beside what lay ahead.', 'quest 1068 description and reward text'),
(40628, 3, 0, 255, 'To truly tend the spirits, the tauren elders must be consulted, and the only one Seereth knew by name was Magatha, said to be very old and very wise, who dwells on Elder Rise in Thunder Bluff. If anyone could marshal the spiritual aid of the tauren, it was she. What the Elder Crone made of the plea is another tale.', 'quest 1063 description (only knows Magatha; very old, knows much; marshal spiritual aid; Elder Rise)'),
(40629, 1, 0, 255, 'When the druids'' people had fallen, Braelyn felt power flood back into her veins, sweet and rushing. The kaldorei, she said, are fools to spurn such gifts, and life without the burning embrace of magic is a pale mockery.', 'quest 1087 reward text'),
(40629, 2, 0, 255, 'Her magic then granted her true sight, and she found what the druids had tried to hide: Keeper Ordanus, spirited away from the peak before she could find him, now concealed far off in Ashenvale. She wanted his head.', 'quest 1088 description (true sight; Raynewood; spirited away from the peak before I could find him; I will have his head); ashenvale.json Raynewood Retreat entry (Ordanus hiding at the top of the tree)'),
(40629, 3, 0, 255, 'When his head was brought to her, Braelyn told more of her errand. Her master had sent her to the peak expecting her only to slaughter the night elves crawling over the ruined temple of Azshara, which she called her own people''s, but Ordanus had slipped her grasp. She had known him long ago, and gloated that the arrogant keeper''s head did not rise so high now.', 'quest 1088 request and reward text'),
(40629, 4, 0, 255, 'Last, she revealed a secret wrung from one of the druids: a key hidden in a small lantern at the entrance of the Talon Den unlocks the druids'' caches, and through them the hoard within.', 'quest 1089 description (extract some details from one of them; Gatekeeper''s Key in a lantern; caches; hoard)'),
(40630, 1, 0, 255, 'Kaela was alive, camped above the road into Windshear Crag, and she had spent most of her time fighting the Venture Company''s destruction. That a night elf and a gnome must work together showed how grave things were, she admitted, but her companion Gaxim Rustfizzle understood the need, and any help had to begin with him.', 'quest 1070 reward text; quest 1085 description'),
(40630, 2, 0, 255, 'It began with explosions. Goblin crews were driven back while Gaxim gathered his materials: volatile Nitromirglyceronium from an old colleague in Tinker Town, made from potions brought to his door, and a scroll of messaging from Collin Mauren in Stormwind, crafted with debris from a Westfall dust devil, so that the charges could be fired from afar, with wagons of dynamite as the distraction.', 'quest 1071 description and reward text; quests 1072 to 1074 (Lomac Gearstrip, NG-5); quests 1075 to 1077 (Collin Mauren, dust devil debris, scroll of messaging, remote explosive); quest_template_addon: 1079 and 1080 need both 1074 and 1077'),
(40630, 3, 0, 255, 'Under cover of the blasts, the Venture Company''s engineering plans were stolen from the lumber mill south of Cragpool Lake and its letters from Windshear Mine. In the plans Gaxim saw weaknesses to exploit and designs to borrow, and he sent the letters on to Kaela, sure that she and the Sentinels would want to see them.', 'quests 1079 and 1080 reward text; quest 1091 description (take these letters to Kaela; she or the Sentinels will want to know); quest_template_addon: 1091 follows both 1079 and 1080 (exclusive group -1079)'),
(40630, 4, 0, 255, 'Kaela sent word home to Astranaar: she and Gaxim were alive and well on their way to stopping the Venture Company and healing the land. Thenysil was glad to hear it, of Kaela and even of Gaxim, and she believed the mission might strengthen the night elves'' foothold in Stonetalon. She sent the messenger on to Darnassus, where Tyrande Whisperwind herself would wish to give thanks.', 'quest 1082 description and reward text; quest 1081 description (offered on turning in 1082)'),
(40631, 1, 0, 255, 'Harpies, ambushers, slayers and roguefeathers fell until the flock had suffered a great loss. Albagorm knew they would regroup soon, and so he sent word far south, past the Barrens and through Thousand Needles, to the druid Falfindel Waywarder at the edge of Feralas, who has the power to call great forest spirits to help in the vale''s reclamation.', 'quest 1057 reward text; quest 1059 description (offered on turning in 1057)'),
(40631, 2, 0, 255, 'Falfindel judged the keeper wise to send word with such urgency, and he means to call forth aid from the great forest, to travel to the Charred Vale before it is too late.', 'quest 1059 reward text'),
(40632, 1, 0, 255, 'Once the seeds were gathered, Tammra began to chant over them, imbuing them with shamanic power and calling on the blessing of the Earthmother, so that even such small kernels of life might bloom and flourish.', 'quest 6301 description and reward text (I will imbue them with shamanistic power; the blessing of the Earthmother; Tammra begins to chant)'),
(40632, 2, 0, 255, 'The land is in pain, Tammra says, but the cycle of life is a powerful thing. The enchanted seeds were carried west into the heart of the destruction, the Charred Vale, past harpies and raging fire spirits, and planted in mounds of fertile soil. Such seeds resist corruption and will make a foothold for other life. In time the Venture Company will pack up its saws, the fire spirits will calm, the harpies will be pushed out by the land itself, and only then will Stonetalon truly know peace.', 'quest 6381 description, request and reward text; zone_areas: Gaea Dirt Mound 177929 in the Charred Vale'),
(40633, 1, 0, 255, 'Ziz had left a man behind. His man Piznik, sent down to the mines when Gerenzo took over, stayed to gather information, and he knew that Gerenzo had ordered large amounts of a strange gold-green ore to be mined.', 'quest 1090 description (second most important person; sent me to the mines; Ziz told me to stay and gather information; gold-green ore); quest 1092 reward text (telling Piznik to stay behind)'),
(40633, 2, 0, 255, 'Piznik dug out a sample while vermin and tunnel rats swarmed out of the dark, and with far too much attention drawn to them he meant to slip out of the mine himself, sending the ore on to Ziz.', 'quest 1090 reward text; quest 1092 description; smart_scripts 427600 (summons Windshear Vermin and Tunnel Rats)'),
(40633, 3, 0, 255, 'Next came the blueprints of the Super Reaper 6000, Gerenzo''s monstrous woodcutter, taken from a company operator. Ziz could make nothing of the way gnomes think, so he sealed them with the internal documents he had snatched on his way out the door, for Sputtervalve in Ratchet.', 'quest 1093 description and reward text; quest 1094 description (offered on turning in 1093)'),
(40633, 4, 0, 255, 'Sputtervalve answered with orders from higher up. The trade princes disapproved of Razdunk''s dealings with the gnome, and Director Riddlevox wanted Gerenzo removed, a fitting test for Fizziks, though Sputtervalve could only guess who stood behind the Director.', 'quest 1094 reward text; quest 1095 description (offered on turning in 1094)'),
(40633, 5, 0, 255, 'Gerenzo, once a head engineer of Gnomeregan whose secret project had exploded in its makers'' faces, was slain on his platform above Cragpool Lake, and his mechanical arm was carried back to Ziz as proof.', 'quest 1095 reward text (Gnomeregan); quest 1096 description, request and reward text'),
(40634, 1, 0, 255, 'Makaba gave his thanks, but the worst of the lot still lived: Grundig Darkcloud, who led the brutal raid on Aparaje, waits with his personal band of brutes at Grimtotem Post, a little further up the path to the west.', 'quest 6548 reward text (I will never forget); quest 6629 description (offered on turning in 6548)'),
(40634, 2, 0, 255, 'Inside the post waited something Makaba never expected. His daughter Kaya, believed lost in the attack, was alive and a prisoner. Freed, she begged to be taken back to Camp Aparaje before her captors noticed she was gone, for from there she knew the way home, and her father would be desperate to know she was safe.', 'quest 6523 description'),
(40634, 3, 0, 255, 'Grimtotem brutes, ruffians and sorcerers struck again along the way, but Kaya reached the ruins of her village and set off home from there. Makaba rejoiced: Kaya was alive. He sent the good news on to Sun Rock Retreat, to her aunt, Tammra Windfield.', 'creature_text 11856 and npc_kaya_flathoof (ambush by Ruffian, Brute, Sorcerer; I know my way back from here); quest 6523 reward text (Kaya is alive); quest 6401 description (offered on turning in 6523)'),
(40634, 4, 0, 255, 'At Sun Rock Retreat the news reached Tammra Windfield, Kaya''s aunt, who like Makaba had thought her niece lost in the brutal attack on the village. She could scarcely believe it: Kaya was alive, and that was good news indeed.', 'quest 6401 description and reward text (we had thought she was lost; my niece Kaya is alive)'),
(40635, 1, 0, 255, 'The crystals confirmed the legend: they bore a trace of earthen magic. The kobolds must have dug deep enough to uncover an earthen, and the earthen were made by the titans to shape the very land. Mor''rogal shook his head at the threat and set about enchanting the samples to use against the kobolds'' plot.', 'quest 6421 request and reward text'),
(40635, 2, 0, 255, 'The resonite cask at the bottom of the cave houses a slumbering earthen named Goggeroc. Mor''rogal enchanted a crystal to smash the cask open, knowing the earthen would wake weak from his long slumber, and that weakness was the one chance to slay him.', 'quest 6481 description and request text'),
(40635, 3, 0, 255, 'Goggeroc was slain while that weakness lasted. Mor''rogal feared what such a being might have meant for all of Kalimdor, and he counted Stonetalon and Kalimdor alike in debt to the one who struck him down.', 'quest 6481 reward text');
